/bin/bash -lc "python3 - <<'PY'
import os, re
root='/mnt/data/LSF/data/officeqa/text'
patterns=[re.compile(p,re.I) for p in [r'net individual income tax receipts', r'individual income tax receipts', r'receipts for the quarter', r'most recent quarter']]
for fn in sorted(os.listdir(root)):
    path=os.path.join(root,fn)
    try:
        txt=open(path,encoding='utf-8',errors='ignore').read()
    except Exception:
        continue
    if any(p.search(txt) for p in patterns):
        print(fn)
        for p in patterns:
            m=p.search(txt)
            if m:
                idx=m.start()
                print(txt[max(0,idx-180):idx+500].replace('\\n',' '))
                break
        print('---')
PY"

